// Berechne die nächsten N Werktage
const daysAhead = $input.first().json.body.days_ahead || 5;
const durationMinutes = $input.first().json.body.duration_minutes || 20;

const workdays = [];
const now = new Date();
let d = new Date(now);
d.setDate(d.getDate() + 1); // Ab morgen

while (workdays.length < daysAhead) {
  const day = d.getDay();
  if (day >= 1 && day <= 5) { // Mo-Fr
    workdays.push(new Date(d));
  }
  d.setDate(d.getDate() + 1);
}

// timeMin = morgen 00:00, timeMax = letzter Werktag 23:59
const timeMin = workdays[0].toISOString();
const timeMax = new Date(workdays[workdays.length - 1]);
timeMax.setHours(23, 59, 59);

return [{
  json: {
    timeMin: timeMin,
    timeMax: timeMax.toISOString(),
    durationMinutes: durationMinutes,
    workdays: workdays.map(d => d.toISOString().split('T')[0])
  }
}];

// Daten aus vorherigen Nodes
const dateRange = $('Datumsbereich berechnen').first().json;
const durationMinutes = dateRange.durationMinutes;
const workdays = dateRange.workdays;

// Alle bestehenden Events sammeln
const existingEvents = $('Google Calendar – Events abrufen').all().map(item => ({
  start: new Date(item.json.start.dateTime || item.json.start.date),
  end: new Date(item.json.end.dateTime || item.json.end.date)
}));

// Deutsche Wochentage
const dayNames = ['Sonntag', 'Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag'];
const monthNames = ['Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'];

// Freie Slots berechnen
const slots = [];
const slotDuration = durationMinutes * 60 * 1000; // ms

for (const dayStr of workdays) {
  const day = new Date(dayStr + 'T00:00:00');

  // Slots von 09:00 bis 18:00
  for (let hour = 9; hour < 18; hour++) {
    for (let min = 0; min < 60; min += 20) {
      const slotStart = new Date(day);
      slotStart.setHours(hour, min, 0, 0);
      const slotEnd = new Date(slotStart.getTime() + slotDuration);

      // Nicht über 18:00 hinaus
      const endOfDay = new Date(day);
      endOfDay.setHours(18, 0, 0, 0);
      if (slotEnd > endOfDay) continue;

      // Prüfe ob Slot mit bestehendem Event überlappt
      const isBlocked = existingEvents.some(ev => 
        slotStart < ev.end && slotEnd > ev.start
      );

      if (!isBlocked) {
        const dayName = dayNames[slotStart.getDay()];
        const dayNum = slotStart.getDate();
        const monthName = monthNames[slotStart.getMonth()];
        const timeStr = `${String(hour).padStart(2, '0')}:${String(min).padStart(2, '0')}`;

        slots.push({
          date: `${dayName}, ${dayNum}. ${monthName}`,
          time: timeStr,
          slot_id: `${dayStr}_${timeStr.replace(':', '')}`,
          iso_date: dayStr,
          iso_start: slotStart.toISOString()
        });
      }
    }
  }
}

// Max 6 Slots zurückgeben (gut verteilt über die Tage)
const maxSlots = 6;
let selectedSlots = [];

if (slots.length <= maxSlots) {
  selectedSlots = slots;
} else {
  // Verteile gleichmäßig über die Tage
  const byDay = {};
  for (const s of slots) {
    if (!byDay[s.iso_date]) byDay[s.iso_date] = [];
    byDay[s.iso_date].push(s);
  }
  const days = Object.keys(byDay);
  const perDay = Math.max(1, Math.floor(maxSlots / days.length));

  for (const day of days) {
    const daySlots = byDay[day];
    // Wähle Slots: morgens, mittags, nachmittags
    const indices = [];
    if (daySlots.length <= perDay) {
      selectedSlots.push(...daySlots);
    } else {
      const step = Math.floor(daySlots.length / perDay);
      for (let i = 0; i < perDay && i * step < daySlots.length; i++) {
        selectedSlots.push(daySlots[i * step]);
      }
    }
    if (selectedSlots.length >= maxSlots) break;
  }
  selectedSlots = selectedSlots.slice(0, maxSlots);
}

return [{
  json: {
    slots: selectedSlots.map(({ iso_start, iso_date, ...rest }) => rest)
  }
}];
